<template>
  <div class="event-panel">
    <div
      :class="['action-button', { disabled: viewMode === 'year' }]"
      :title="viewMode === 'month' ? '返回全年' : '返回'"
      @click="viewMode === 'month' && emit('exit-month')"
    >
      <el-icon :size="18"><Back /></el-icon>
    </div>

    <div class="action-button" title="添加" @click="emit('open-add')">
      <el-icon :size="18"><Plus /></el-icon>
    </div>

    <div :class="['action-button', { active: isEditMode }]" title="编辑" @click="emit('toggle-edit')">
      <el-icon :size="18"><Edit /></el-icon>
    </div>

    <div class="divider"></div>

    <div class="event-circles">
      <el-tooltip
        v-for="event in events"
        :key="event.id"
        placement="right"
        effect="dark"
      >
        <template #content>
          <div>{{ event.name }}</div>
        </template>
        <div
          :class="['event-circle', { selected: selectedEventId === event.id }]"
          :style="{ backgroundColor: event.color }"
          @click="emit('event-click', event.id)"
        >
          <span class="event-initial">{{ event.iconText || event.name.charAt(0) }}</span>
          <div v-if="isEditMode" class="edit-badge">
            <el-icon :size="12"><Edit /></el-icon>
          </div>
          <span class="event-count-badge">
            {{ getEventCount(event.id) }}
          </span>
        </div>
      </el-tooltip>
    </div>

    <div class="spacer"></div>

    <div class="more-button" @click="emit('open-manage')">
      <span class="more-dots">⋯</span>
    </div>

    <div class="divider"></div>

    <div :class="['action-button', 'clear-button', { active: isClearMode }]" @click="emit('toggle-clear')">
      <el-icon :size="18"><Delete /></el-icon>
    </div>

    <div class="divider"></div>

    <div class="year-selector-vertical">
      <div class="year-button" title="下一年" @click="emit('change-year', 1)">
        <el-icon :size="12"><ArrowUp /></el-icon>
      </div>
      <div class="year-display">
        {{ currentYear }}
      </div>
      <div class="year-button" title="上一年" @click="emit('change-year', -1)">
        <el-icon :size="12"><ArrowDown /></el-icon>
      </div>
    </div>

    <div class="divider"></div>

    <el-tooltip content="导入数据" placement="right" effect="dark">
      <div class="action-button" @click="triggerImport">
        <el-icon :size="18"><Upload /></el-icon>
      </div>
    </el-tooltip>

    <el-tooltip content="导出数据" placement="right" effect="dark">
      <div class="action-button" @click="emit('export-data')">
        <el-icon :size="18"><Download /></el-icon>
      </div>
    </el-tooltip>

    <input
      ref="fileInput"
      type="file"
      accept=".json"
      style="display: none;"
      @change="emit('import-data', $event)"
    />
  </div>
</template>

<script setup>
import { defineEmits, defineProps, ref } from 'vue'
import { ArrowDown, ArrowUp, Back, Delete, Download, Edit, Plus, Upload } from '@element-plus/icons-vue'

defineProps({
  viewMode: {
    type: String,
    required: true
  },
  isEditMode: {
    type: Boolean,
    required: true
  },
  isClearMode: {
    type: Boolean,
    required: true
  },
  events: {
    type: Array,
    required: true
  },
  selectedEventId: {
    type: String,
    default: null
  },
  currentYear: {
    type: Number,
    required: true
  },
  getEventCount: {
    type: Function,
    required: true
  }
})

const emit = defineEmits([
  'exit-month',
  'open-add',
  'toggle-edit',
  'event-click',
  'open-manage',
  'toggle-clear',
  'change-year',
  'import-data',
  'export-data'
])

const fileInput = ref(null)

const triggerImport = () => {
  fileInput.value?.click()
}
</script>
